def _gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def _continued_fraction(num: int, den: int) -> list[int]:
    # den > 0, num and den coprime.
    # Returns [a0; a1, a2, ...] using the usual floor-based CF.
    a0 = num // den
    rem = num - a0 * den
    cf = [a0]
    if rem == 0:
        return cf

    a = den
    b = rem
    while b:
        q = a // b
        cf.append(q)
        a, b = b, a - q * b
    return cf


def best_rational(num: int, den: int, max_den: int, side: int = 0) -> tuple[int, int]:
    if den == 0:
        raise ValueError("den == 0")
    if max_den < 1:
        raise ValueError("max_den must be at least 1")
    if side not in (-1, 0, 1):
        raise ValueError("side must be -1, 0, or 1")

    if num == 0:
        return (0, 1)

    g = _gcd(abs(num), abs(den))
    a = num // g
    b = den // g
    if b < 0:
        a = -a
        b = -b

    if a == 0:
        return (0, 1)

    # Exact rational already has a denominator within the limit.
    if b <= max_den:
        return (a, b)

    cf = _continued_fraction(a, b)

    # Compute convergents until the next convergent would exceed max_den.
    # At stop, current convergent p_curr/q_curr is the last one with q_curr <= max_den,
    # and q_next = next_a * q_curr + q_prev > max_den.
    p_im2, q_im2 = 0, 1  # convergent k-2
    p_im1, q_im1 = 1, 0  # convergent k-1
    found = False

    p_prev = q_prev = None
    p_curr = q_curr = None
    next_a = None
    n = 0

    for k, aa in enumerate(cf):
        p = aa * p_im1 + p_im2
        q = aa * q_im1 + q_im2

        if k + 1 < len(cf):
            q_next = cf[k + 1] * q + q_im1
            if q_next > max_den:
                found = True
                p_prev, q_prev = p_im1, q_im1
                p_curr, q_curr = p, q
                next_a = cf[k + 1]
                n = k
                break

        p_im2, p_im1 = p_im1, p
        q_im2, q_im1 = q_im1, q

    if not found:
        # Should not happen for reduced b > max_den, but keep a safe fallback.
        p_prev, q_prev = 0, 1
        p_curr, q_curr = a, b
        next_a = 1
        n = len(cf) - 1

    # If possible, build the best intermediate fraction on the opposite side.
    # Otherwise the previous convergent itself is the opposite-side neighbour.
    max_m = 0
    if q_curr > 0:
        max_m = (max_den - q_prev) // q_curr
        if max_m > next_a:
            max_m = next_a
        if max_m < 0:
            max_m = 0

    if max_m == 0:
        p_opp = p_prev
        q_opp = q_prev
    else:
        p_opp = p_prev + max_m * p_curr
        q_opp = q_prev + max_m * q_curr

    # Even convergents are below x; odd convergents are above x.
    if n % 2 == 0:
        p_left, q_left = p_curr, q_curr
        p_right, q_right = p_opp, q_opp
    else:
        p_left, q_left = p_opp, q_opp
        p_right, q_right = p_curr, q_curr

    if side == -1:
        return (p_left, q_left)
    if side == 1:
        return (p_right, q_right)

    # Compare |a/b - p_left/q_left| and |a/b - p_right/q_right| exactly.
    # Since q_left, q_right > 0:
    # left distance   = (a*q_left - p_left*b) / (b*q_left)
    # right distance  = (p_right*b - a*q_right) / (b*q_right)
    left_num = a * q_left - p_left * b
    right_num = p_right * b - a * q_right

    lhs = left_num * q_right
    rhs = right_num * q_left

    if lhs < rhs:
        return (p_left, q_left)
    if lhs > rhs:
        return (p_right, q_right)

    # Ties: smaller denominator first, then smaller numerator.
    if q_left < q_right:
        return (p_left, q_left)
    if q_right < q_left:
        return (p_right, q_right)
    if p_left <= p_right:
        return (p_left, q_left)
    return (p_right, q_right)
